 function documentGroups(d){const done=new Set();return d.itemIds.map(item).filter(Boolean).flatMap(i=>{const key=i.passageId?'set-'+i.passageId:''+i.id;if(done.has(key))return [];done.add(key);return [{key,items:i.passageId?d.itemIds.map(item).filter(x=>x?.passageId===i.passageId):[i]}];});}
 function documentDetail(kind,id){const original=doc(id);if(!original)return notFound();const editable=original.status==='R',d=editable?beginEdit('review',id,original).data:original,over=kind==='hml'&&d.questionCount>50;if(over)d.paperReg='N';
  const info={W:'파일 파싱을 기다리고 있습니다.',P:'파일 파싱 중입니다. 페이지를 닫아도 처리가 계속됩니다.',M:'AI 메타 추천 중입니다. 완료 후 자동 승인됩니다.',D:'폐기된 시험지입니다. 복원할 수 없으며 조회만 가능합니다.',F:'파일 파싱 또는 메타 추천에 실패했습니다. 원본을 수정한 뒤 신규 등록해 주세요.'};
  return heading(kind==='hml'?'HML 상세':'디피니션 상세')+`<div class="document-detail">`+(info[d.status]?notice(info[d.status],d.status==='F'||d.status==='D'?'warning':''):'')+panel('기본 정보',`<div class="two-col"><div class="form-section">${kv('시험지 ID',String(d.id)+' '+tag(d.status))}${kv('원본 파일',`${esc(d.file)} ${btn('다운로드','download-doc',`data-id="${d.id}"`,'small')}`)}${kv('출처',esc(source(d.sourceId)?.code))}${kv('단원 코드',esc(d.unitCode))}${kv('페이지',`${d.start} ~ ${d.end}`)}${kv('용도',d.usage==='C'?'공통':'교사용')}${kv('등록',`demo.editor · ${d.created}`)}${kv('문항 수',`${d.questionCount}문항`)}</div><div>${kind==='hml'?field('평가지 등록여부 <span class="required">*</span>',`<div class="inline"><label><input type="radio" name="paperReg" value="Y" data-bind="paperReg" ${d.paperReg==='Y'?'checked':''} ${!editable||over?'disabled':''}>등록</label><label><input type="radio" name="paperReg" value="N" data-bind="paperReg" ${d.paperReg==='N'?'checked':''} ${!editable||over?'disabled':''}>미등록</label></div>${over?'<p class="error-text">* 50문항이 넘는 HML은 평가지로 등록할 수 없습니다.</p><p class="muted small-text">변경 예정 정책을 적용했습니다. HML 등록과 문항은 유지됩니다.</p>':''}`):''}${field('비고',`<textarea data-bind="remark" maxlength="1000" ${!editable?'disabled':''}>${esc(d.remark)}</textarea>`)}</div></div>`)+
   panel('분리 문항 리스트',`${d.questionCount>d.itemIds.length?notice(`전체 ${d.questionCount}문항 중 화면에는 ${d.itemIds.length}개 예시만 표시합니다. 정책 판단에는 전체 문항 수를 사용합니다.`):''}<div class="review-grid ${kind==='definition'?'definition-review':''}">${documentGroups(d).map((g,n)=>`<section class="review-card" id="review-${g.key}"><div class="head"><span>#${n+1} ${g.items[0].passageId?'세트 · 지문ID '+g.items[0].passageId:'문항ID '+g.items[0].id}</span>${editable?select('judgment',[['W','등록대기'],['S','등록성공'],['F','등록실패'],['D','삭제']],d.judgments[g.key]||'W',`data-judgment="${g.key}"`,null).replace('<option value="W"','<option disabled value="W"'):tag(d.status==='D'?'D':d.judgments[g.key]||'S')}</div>${g.items[0].passageId?`<div class="review-child">${esc(g.items[0].passage)}</div>`:''}${g.items.map(i=>`<div class="review-child"><span class="id">문항ID ${i.id}</span>${questionHtml(i,{header:false})}${!editable&&d.status!=='D'&&d.judgments[g.key]!=='D'?`<div class="actions">${link('상세','/items/'+i.id,'btn small')}${btn('문항 수정','item-edit',`data-id="${i.id}"`,'small')}</div>`:''}</div>`).join('')}</section>`).join('')}</div>${!d.itemIds.length?'<div class="empty">분리 문항이 아직 없습니다.</div>':''}`)+
   `<div class="page-actions">${link('목록','/'+kind,'btn')}${editable?btn('폐기','doc-discard',`data-id="${id}"`,'danger')+btn('승인','doc-approve',`data-id="${id}"`,'primary'):''}${['W','P','M'].includes(d.status)?btn('예시 처리 완료','doc-finish',`data-id="${id}"`):''}</div></div>`;
 }
 function paperRows(groups,editable=false){return `<div class="table-wrap paper-items"><table><thead><tr>${[...(editable?['']:[]),'순서','문항 ID','문제','형태','난이도','단원 코드','문항 상태',...(editable?['제외']:[])].map(h=>`<th>${h}</th>`).join('')}</tr></thead>${groups.map((ids,index)=>`<tbody class="paper-group" ${editable?'draggable="true"':''} data-group-index="${index}">${ids.map(item).filter(Boolean).map((i,n)=>`<tr>${editable&&n===0?`<td rowspan="${ids.length}"><span class="handle" aria-label="순서 이동">${icon('move')}</span><div class="paper-move-buttons">${btn('위로','paper-move',`data-index="${index}" data-delta="-1" ${index===0?'disabled':''}`,'small')}${btn('아래로','paper-move',`data-index="${index}" data-delta="1" ${index===groups.length-1?'disabled':''}`,'small')}</div></td>`:''}${n===0?`<td rowspan="${ids.length}">${index+1}${ids.length>1?`<small class="muted"> 세트 ${ids.length}문항</small>`:''}</td>`:''}<td>${i.id}</td><td><div class="question-cell">${link(esc(i.stem),'/items/'+i.id)}${i.passageId?`<small>지문 ID ${i.passageId}</small>`:''}</div></td><td>${category(i.type)} > ${i.type.includes('MA')?'다답형':'단답형'} > ${i.type.startsWith('OB')?'N지 선다':'일반형'}</td><td>${i.difficulty}</td><td>${esc(i.unitCodes[0])}</td><td>${statusNames[i.status]}</td>${editable&&n===0?`<td rowspan="${ids.length}">${btn('제외','paper-remove',`data-index="${index}" ${groups.length===1?'disabled title="최소 1그룹을 유지해야 합니다."':''}`,'small danger')}</td>`:''}</tr>`).join('')}</tbody>`).join('')}</table></div>`;}

 function paperPage(id,editing=false){const original=paper(id);if(!original)return notFound();if(editing&&original.status==='D')return notFound('폐기 평가지의 수정은 잠겨 있습니다.');const p=editing?beginEdit('paper',id,original).data:original,docRef=doc(p.docId),src=source(docRef?.sourceId),count=p.legacyCount||p.groups.flat().length,units=Array.from(new Set(p.groups.flat().map(item).filter(Boolean).flatMap(i=>i.unitCodes))),control=(label,html)=>`<div class="paper-control">${field(label,html)}</div>`;
  return heading(editing?'평가지 수정':'평가지 상세','평가지 관리')+`<div class="paper-page">`+(!editing&&p.automaticStatus?.status===p.status?notice(esc(p.automaticStatus.reason),'warning'):'')+panel('기본 정보',`<div class="two-col"><div class="paper-facts-column">${kv('평가지 ID',p.id+' ('+p.version+')')}${editing?control('평가지명 <span class="required">*</span>',input('name',p.name,'data-bind="name" maxlength="255" required')):kv('평가지명',esc(p.name))}${editing?control('상태',select('status',[['R','초안'],['Y','사용'],['N','미사용'],['D','폐기']],p.status,'data-bind="status"',null)):kv('상태',({R:'초안',Y:'사용',N:'미사용',D:'폐기'})[p.status])}${kv('생성 방식',p.method==='HML'?'HML 생성':p.method)}${kv('단원 코드',units.map(code=>`[${esc(code)}]<br><small class="muted">${esc(db.units.find(u=>u.code===code)?.path)}</small>`).join('<br>'))}${kv('등록',`demo.editor · ${p.created}`)}</div><div class="paper-facts-column">${kv('시험지',docRef?link(docRef.id+' | '+esc(docRef.file),'/'+docRef.kind+'/'+docRef.id):'−')}${kv('출처',src?`[${esc(src.code)}]<br>${esc(src.name)}`:'-')}${editing?control('페이지 <span class="required">*</span>',`<div class="inline">${input('start',p.start,'type="number" min="1" data-bind="start"')} ~ ${input('end',p.end,'type="number" min="1" data-bind="end"')}</div>`):kv('페이지',p.start+' ~ '+p.end)}${editing?control('용도 <span class="required">*</span>',select('usage',[['C','공통'],['T','교사용']],p.usage,'data-bind="usage"',null)):kv('용도',p.usage==='C'?'공통':'교사용')}${kv('문제 구성',Array.from(new Set(p.groups.flat().map(item).filter(Boolean).map(i=>category(i.type)))).join(', '))}${kv('문항 수',count+'문항')}</div></div>`)+
  (!editing?panel('배포',table(['서비스','배포 버전','승인 여부','서비스 상태','최근 배포','배포'],['AI출제마법사 CMS','개발 서비스'].map(t=>tr([t,p.deploymentRecords?.[t]?.version||(p.deployed.includes(t)?'기록 없음':'−'),p.deployed.includes(t)?'미확인(모의)':'−',p.deployed.includes(t)?'배포됨':'−',esc(p.deploymentRecords?.[t]?.at||'−'),paperItems(p).filter(i=>i?.status!=='D'&&!i?.deployed.includes(t)).length+'건 미배포 '+btn('조회','paper-undeployed',`data-id="${p.id}" data-target="${t}"`,'small')]))),btn('배포하기','paper-deploy',`data-id="${id}" ${p.status!=='Y'?'disabled title="사용 평가지만 배포할 수 있습니다."':''}`,'primary')):'')+
  panel('포함 문항 ('+count+')',(p.legacyCount?notice(`전체 ${p.legacyCount}문항 중 ${p.groups.flat().length}개 예시를 표시합니다. 원본 보존·초과 평가지 정리 흐름을 확인하는 예시입니다.`):'')+paperRows(p.groups,editing),editing?btn('문항 추가','paper-add','','primary'):'')+`<div class="page-actions">${editing?btn('취소','cancel-edit',`data-title="평가지 수정 취소" data-to="/papers/${id}"`)+btn('저장','paper-save','','primary'):link('목록','/papers','btn')+(p.status==='D'?'<span class="btn" aria-disabled="true">수정</span>':link('수정','/papers/'+id+'/edit','btn primary'))}</div></div>`;
 }

 function twinsPage(id){if(id){const g=db.twins.find(x=>x.id===+id);if(!g)return notFound();const members=g.members.flatMap(member=>g.type==='set'?db.items.filter(i=>i.passageId===member):[item(member)]).filter(Boolean);return heading('쌍둥이 그룹 상세')+panel('그룹 정보',`<div class="twin-group-info">${kv('그룹 ID',g.id)}${kv('유형',g.type==='set'?'세트 문항':'단일 문항')}${kv('개수',g.members.length+(g.type==='set'?'세트':'개'))}${kv('수정자','demo.editor')}${kv('수정일시',g.updated)}</div>`)+table(['문항 ID','문제','단원코드','형태 / 난이도','상태'],members.map(i=>tr([i.id,`<div class="question-cell">${link(esc(i.stem),'/items/'+i.id)}${i.passageId?`<small>세트 ${i.passageId}</small>`:''}</div>`,esc(i.unitCodes.join(', ')),`${category(i.type)} > ${i.type.includes('MA')?'다답형':'단답형'}<br>${i.difficulty}`,statusNames[i.status]])))+`<div class="page-actions">${link('목록','/twins','btn')}</div>`;}
  const p=paginate('twins',db.twins);return heading('쌍둥이 그룹 관리')+p.toolbar+table(['그룹 ID','유형','대표 문제','개수','수정자','수정일시'],p.records.map(g=>{const i=g.type==='set'?db.items.find(i=>i.passageId===g.members[0]):item(g.members[0]);return tr([g.id,g.type==='set'?'세트 문항':'단일 문항',`<div class="question-cell">${link(esc(i?.stem||'예시 문항'),'/twins/'+g.id)}</div>`,g.members.length+(g.type==='set'?'세트':'개'),'demo.editor',g.updated]);}))+p.footer;}

 function openTwins(id,tab='current'){const i=item(id),kind=i.passageId?'set':'single',key=i.passageId||i.id,g=twinGroup(i),members=g?.members||[key];let m;
  const draw=(query='',f={})=>{m._criteria=f;m._query=query;const candidates=db.items.filter(c=>candidateMatches(c,f,query)),seen=new Set();$('.modal-body',m).innerHTML=`<div class="tabs">${btn('현재 쌍둥이','twins-tab',`data-id="${id}" data-tab="current"`,tab==='current'?'active':'')}${btn('쌍둥이 추가','twins-tab',`data-id="${id}" data-tab="add"`,tab==='add'?'active':'')}</div>${tab==='current'?table(['문항 / 세트 ID','문제','단원 코드','상태','해제'],members.flatMap(member=>{const records=kind==='set'?db.items.filter(v=>v.passageId===member):[item(member)];return records.filter(Boolean).map((v,n)=>tr([`${v.id}${v.passageId?'<br>세트 '+v.passageId:''}`,link(esc(v.stem),'/items/'+v.id),v.unitCodes[0],tag(v.status),n===0?btn('해제','twins-remove',`data-id="${id}" data-member="${member}" ${members.length<=1?'disabled':''}`,'small danger'):'']));})): `<form data-form="twins-search" data-id="${id}">${candidateFilters({...f,q:query},true)}</form><p class="muted">본인·현재 멤버·폐기 문항·단건/세트가 다른 후보는 추가할 수 없습니다.</p>${table(['문항 ID','문제','형태 / 난이도','세트 ID','상태','매핑 정보','추가'],modalRows(m,candidates.filter(c=>{const k=c.passageId||c.id;if(seen.has(k))return false;seen.add(k);return true;})).map(c=>{const ckey=c.passageId||c.id,blocked=members.includes(ckey)||c.status==='D'||!!c.passageId!==!!i.passageId,reason=members.includes(ckey)?'현재 쌍둥이':c.status==='D'?'폐기':!!c.passageId!==!!i.passageId?'유형 다름':'추가 가능';return tr([c.id,`<div class="question-cell">${esc(c.stem)}</div>`,category(c.type)+' / '+c.difficulty,c.passageId||'−',tag(c.status),reason,btn('추가','twins-add',`data-id="${id}" data-member="${ckey}" ${blocked?'disabled':''}`,'small')] );}))+modalPager(m)}`}`;};m=modal('쌍둥이 문항 관리','',[{label:'닫기',fn:(_,m)=>closeModal(m)}],{wide:true});m._draw=draw;m._twinId=id;m._tab=tab;draw();}
 function itemSources(id,tab='current'){const i=item(id);const m=modal('출처 관리',`<div class="tabs">${btn('현재 출처','source-tab',`data-id="${id}" data-tab="current"`,tab==='current'?'active':'')}${btn('출처 추가','source-tab',`data-id="${id}" data-tab="add"`,tab==='add'?'active':'')}</div>${tab==='add'?`<form data-form="relation-search" data-id="${id}"><div class="filters">${field('검색 기준',select('criterion',[['code','출처코드'],['name','출처명']],'code','',null))}${field('검색어',input('q','','placeholder="출처 검색"'),'span-2')}${taxonomyFields({}).replace(/ required/g,'')}${field('용도',select('usage',[['C','공통'],['T','교사용']]))}</div><div class="actions filter-actions">${btn('초기화','relation-reset')}<button type="submit" class="btn primary">조회</button></div></form>`:''}<div data-relation-results></div>`,[{label:'닫기',fn:(_,m)=>closeModal(m)}],{wide:true});m._search=f=>{m._criteria=f;const rows=(tab==='current'?i.sourceRefs.map(r=>source(r.id)).filter(Boolean):db.sources.filter(s=>(!f?.q||String(s[f.criterion]).includes(f.q))&&['curriculum','school','subjectGroup','subject','grade','semester','usage'].every(k=>!f?.[k]||s[k]===f[k]))); $('[data-relation-results]',m).innerHTML=table(['출처코드 / 출처명','페이지','용도','상태',tab==='current'?'수정 / 해제':'추가'],modalRows(m,rows).map(s=>{const ref=i.sourceRefs.find(r=>r.id===s.id);return `<tr data-source-row="${s.id}"><td class="left">${esc(s.code)}<br>${esc(s.name)}</td><td><div class="inline">${input('start',ref?.start||1,'type="number" min="1" aria-label="시작 페이지"')} ~ ${input('end',ref?.end||1,'type="number" min="1" aria-label="끝 페이지"')}</div></td><td>${select('usage',[['C','공통'],['T','교사용']],ref?.usage||'C','',null)}</td><td>${tag(s.status,true)}</td><td><div class="actions">${tab==='current'?btn('수정','relation-update',`data-id="${id}" data-source="${s.id}"`,'small')+btn('해제','relation-remove',`data-id="${id}" data-source="${s.id}" ${i.sourceRefs.length===1?'disabled':''}`,'small danger'):btn(ref?'연결됨':'추가','relation-add',`data-id="${id}" data-source="${s.id}" ${ref||s.status==='N'?'disabled':''}`,'small')}</div></td></tr>`;}))+modalPager(m);};m._search({});}
 function paperItems(p){return [...new Set(p.groups.flat())].map(item);}
 function paperDeployCheck(p,target){
  const all=paperItems(p),included=all.filter(i=>i?.status!=='D');
  if(p.status!=='Y')return {allowed:false,reason:'사용 평가지만 배포할 수 있습니다.'};
  if(!all.length||all.some(i=>!i))return {allowed:false,reason:'포함 문항 정보를 확인할 수 없습니다.'};
  if(!included.length)return {allowed:false,reason:'폐기 문항을 제외하면 배포할 문항이 없습니다.'};
  if(included.some(i=>i.status!=='Y'))return {allowed:false,reason:'사용 중지(미사용 N)·초안·실패 문항이 포함되어 배포할 수 없습니다.'};
  const missing=included.filter(i=>!i.deployed.includes(target));
  if(missing.length)return {allowed:false,reason:`${missing.length}건의 문항을 이 대상에 먼저 배포해 주세요.`};
  return {allowed:true,items:included};
 }
 function syncPaperStates(){
  for(const p of db.papers){
   if(p.status==='D')continue;
   const included=paperItems(p);if(!included.length||included.some(i=>!i)||included.some(i=>i.status==='Y'))continue;
   const next=included.every(i=>i.status==='D')?'D':included.some(i=>i.status==='N')?'N':null;
   if(!next||next===p.status)continue;
   p.history.push({version:p.version,at:now(),name:p.name,status:p.status});p.version=Date.now();p.status=next;
   p.automaticStatus={status:next,at:now(),reason:next==='D'?'포함 문항이 모두 폐기되어 자동 폐기되었습니다.':'사용 문항이 없고 사용 중지(미사용 N) 문항이 있어 자동으로 미사용 처리되었습니다. 문항이 사용으로 돌아와도 관리자 수동 변경이 필요합니다.'};
   db.events.unshift({at:now(),message:`평가지 ${p.id} 자동 ${next==='D'?'폐기':'미사용(사용 중지)'} 처리`});
  }
 }
 function paperUseError(original,p){
  if(p.status!=='Y')return '';
  const included=paperItems(p);
  if(!included.length||included.some(i=>!i))return '포함 문항 정보를 확인해 주세요.';
  if(original.status==='R'&&included.some(i=>i.status!=='Y'))return '초안에서 사용으로 변경하려면 모든 문항이 승인(사용) 상태여야 합니다. 폐기 문항도 예외로 제외하지 않습니다.';
  if(original.status==='N'&&!included.some(i=>i.status==='Y'))return '사용 중지(미사용 N) 평가지의 승인 복귀에는 승인(사용) 문항이 1개 이상 필요합니다.';
  return '';
 }
 function deploy(id,isPaper=false){
  const r=isPaper?paper(id):item(id),targets=['AI출제마법사 CMS','개발 서비스'];if(!r)return;
  if(!isPaper&&r.status!=='Y')return alertBox('문항 배포','사용(Y) 상태의 문항만 배포할 수 있습니다.');
  if(isPaper&&r.status!=='Y')return alertBox('평가지 배포','사용 평가지만 배포할 수 있습니다.');
  const check=t=>isPaper?paperDeployCheck(paper(id),t):{allowed:item(id)?.status==='Y',reason:'사용(Y) 상태의 문항만 배포할 수 있습니다.'};
  const m=modal(isPaper?'평가지 배포':'문항 배포',notice('목업의 배포 상태만 변경합니다. 실제 서비스로 전송하지 않습니다.')+(isPaper?'<p>폐기 문항은 배포 대상과 선행 배포·존재 검사에서 제외합니다. 나머지 문항을 선택한 대상에 먼저 배포해야 합니다. 포함 문항을 함께 배포하지 않습니다.</p>':'<p>사용(Y) 상태의 문항만 배포할 수 있습니다.</p>')+targets.map(t=>{const eligibility=check(t);return `<p><label><input type="checkbox" name="deployTarget" value="${t}" ${!eligibility.allowed?'disabled':''}>${t}</label> ${!eligibility.allowed?`<span class="error-text">${esc(eligibility.reason)}</span>`:r.deployed.includes(t)?'<span class="muted">이미 배포됨 · 재배포</span>':''}</p>`;}).join('')+'<p data-redeploy class="muted"></p>',[{label:'취소',fn:(_,m)=>closeModal(m)},{label:'배포',kind:'primary',disabled:true,fn:(_,m)=>{
   const selected=$$('input[name=deployTarget]:checked',m).map(x=>x.value);if(!selected.length)return;
   for(const t of selected){if(!targets.includes(t))return errorIn(m,'유효한 배포 대상을 선택해 주세요.');const eligibility=check(t);if(!eligibility.allowed)return errorIn(m,eligibility.reason);}
   selected.forEach(t=>{if(!r.deployed.includes(t))r.deployed.push(t);r.deploymentRecords=r.deploymentRecords||{};r.deploymentRecords[t]={version:r.version,at:now(),...(isPaper?{itemIds:check(t).items.map(i=>i.id)}:{})};});
   save('모의 배포: '+id);closeModal(m);render();toast('로컬 예시 배포 상태를 변경했습니다.');
  }}]);
  m.addEventListener('change',()=>{const selected=$$('input[name=deployTarget]:checked',m);$('.modal-foot .primary',m).disabled=!selected.length||selected.some(x=>!check(x.value).allowed);$('[data-redeploy]',m).textContent=selected.some(x=>r.deployed.includes(x.value))?'이미 배포한 대상에 같은 예시 버전을 다시 배포합니다.':'';});
 }
 function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 function notFound(message='해당 예시 데이터를 찾을 수 없습니다.'){return heading('화면 안내')+panel('안내',`<p>${message}</p>${link('홈으로','/home','btn')}`);}
 const routes={REV_HOME_01:'/home',REV_ITM_01:'/items',REV_ITM_02:'/items/2100001',REV_ITM_03:'/items/2100001/edit/meta',REV_ITM_04:'/items/2100001/edit/hml',REV_ITM_05:'/items/2100001/edit/html',REV_ITM_06:'/items/2100001/edit/omr',REV_ITM_07:'/items/2100001/edit/hml',REV_LAB_01:'/lab',REV_LAB_02:'/lab/math',REV_LAB_03:'/lab/omr',REV_LAB_04:'/lab/restore',REV_LAB_05:'/lab/isolation',MST_HML_C01:'/hml',MST_HML_C02:'/hml/new',MST_HML_C03:'/hml/6001',MST_HML_C04:'/hml/6003',MST_DIFI_C01:'/definition',MST_DIFI_C02:'/definition/new',MST_DIFI_C03:'/definition/7001',MST_DIFI_C04:'/definition/7002',MST_TWN_C01:'/twins',MST_TWN_C02:'/twins/3001',REV_PAP_LIST:'/papers',REV_PAP_DETAIL:'/papers/5001',REV_PAP_EDIT:'/papers/5001/edit',REV_SRC_LIST:'/sources',REV_SRC_FORM:'/sources/new',REV_SRC_DETAIL:'/sources/8001',REV_SRC_EDIT:'/sources/8001/edit'};
 function guide(){return heading('목업 안내·화면 구현 목록','목업')+notice('실제 CMS와 연결되지 않는 파일 실행형 목업입니다. 데이터는 예시이며 이 브라우저에만 저장됩니다.')+panel('사용 방법',`<p>왼쪽 메뉴에서 업무를 선택하세요. 예시 데이터 초기화, 내보내기와 가져오기를 제공합니다. 파일 위치를 옮기거나 다른 브라우저로 열면 저장 영역이 달라질 수 있습니다.</p><div class="actions">${btn('데이터 내보내기','export-data')}${btn('데이터 가져오기','import-data')}${btn('예시 데이터 초기화','reset-data','','danger')}</div>`)+panel('모의 처리와 구현 범위',`<ul><li>실제 HML/ZIP 해석 대신 예시 파일명과 지정한 문항 수로 문서를 생성합니다.</li><li>한글 편집기는 텍스트 편집을 제공하며 벤더의 HML 레이아웃 엔진을 포함하지 않습니다.</li><li>수식은 LaTeX 입력과 기본 MathML 미리보기를 제공합니다. 전체 KaTeX 문법·필기 인식은 제공하지 않습니다.</li><li>AI 생성은 예시 복제 결과를 생성하며 배포·캐시·역할별 로그아웃은 로컬 기록만 남깁니다.</li><li>OMR 14유형의 입력·정답·예시 응답을 제공합니다. 영역·선·드래그의 배치와 판정은 목업용이며 서비스 채점 엔진과 다릅니다.</li><li>50문항 초과 정책을 적용합니다. 정확히 50문항과 산정 범위는 구현 전 확인이 필요한 조건입니다.</li></ul>`)+panel('기본 화면 30개',MockCatalog.screens.map(s=>`<div class="coverage-item"><b>${link(esc(s.title),routes[s.id])}</b><span class="muted small-text"> · ${s.id}</span><details><summary>조사한 요소와 정책 ${s.notes.length}개 확인</summary><ul>${s.notes.map(n=>`<li><b>${esc(n.label)}</b><br>${esc(n.body)}</li>`).join('')}</ul></details></div>`).join(''))+panel('모달·팝업 52개',MockCatalog.modals.map(m=>`<div class="coverage-item"><b>${esc(m.title)}</b><span class="muted small-text"> · ${m.id}</span><p>${link('해당 기능이 있는 화면 열기',routes[m.screen])}</p><details><summary>입력 요소와 화면 변형 확인</summary><p>${esc(m.fields.join(' · ')||'확인 안내')}</p><p>버튼: ${esc(m.buttons.join(' · '))}</p><p>변형: ${esc(m.variants.join(' / '))}</p></details></div>`).join(''));}
 function home(){return `<div class="home-greeting">접속자 demo.editor님 환영합니다.</div><section class="home-welcome"><h1>문제은행 마스터 CMS에 접속하셨습니다.</h1><p>왼쪽 메뉴에서 작업을 선택해 주세요.</p></section>`+(!storageOk?notice('브라우저 저장을 사용할 수 없습니다. 현재 탭에서만 변경을 유지하며 데이터 내보내기를 이용할 수 있습니다.','warning'):'');}

 function render(){current=location.hash.slice(1)||'/home';document.body.dataset.route=current;document.body.dataset.section=current.split('/')[1];const parts=current.split('/').filter(Boolean),[key,id,mode,tab]=parts;nav();let html;
  if(key==='home')html=home();else if(key==='guide')html=guide();else if(key==='login')html=`<div class="login-box"><h1>Master CMS 목업 로그인</h1><p>실제 계정 인증을 수행하지 않습니다.</p>${field('예시 계정',input('account','demo.editor','disabled'))}<div class="page-actions">${btn('목업 시작','login','','primary')}</div></div>`;
  else if(key==='items')html=id?(mode==='edit'?CMS.renderEditor?.(+id,tab||'meta'):itemDetail(id)):listPage(key);
  else if(key==='hml'||key==='definition')html=id?(id==='new'?documentNew(key):documentDetail(key,id)):listPage(key);
  else if(key==='sources')html=id?sourcePage(id,mode==='edit'):listPage(key);
  else if(key==='papers')html=id?paperPage(id,mode==='edit'):listPage(key);
  else if(key==='twins')html=twinsPage(id);
  else if(key==='lab')html=CMS.renderLab?.(id)||'';else html=notFound();$('#main').innerHTML=html||notFound();CMS.afterRender?.(parts);
 }
 function updateBind(target){if(!edit)return;const key=target.dataset.bind;let v=target.type==='checkbox'?target.checked:target.type==='number'?(target.value===''?'':+target.value):target.value;if(key){edit.data[key]=v;edit.dirty=true;}if(key==='unitCode'&&$('#unit-options'))$('#unit-options').innerHTML=v.length>=3?db.units.filter(u=>u.code.includes(v)||u.name.includes(v)).slice(0,20).map(u=>`<option value="${u.code}">${u.name}</option>`).join(''):'';
  if(edit.kind==='source'&&key==='school'){edit.data.grade='';edit.data.semester='';render();}else if(edit.kind==='source'&&key==='subjectGroup'){edit.data.subject='';render();}else if(edit.kind==='source'&&key==='book'){edit.data.volume='';render();}
 }
