 on('import-data',()=>{const f=document.createElement('input');f.type='file';f.accept='.json';f.onchange=async()=>{try{const v=JSON.parse(await f.files[0].text());if(v.schema!==1||!['items','sources','docs','papers','twins','units'].every(k=>Array.isArray(v[k])))throw Error('형식');confirm('예시 데이터 가져오기','현재 로컬 데이터를 선택한 파일의 데이터로 교체합니다.','가져오기',()=>{db=v;save();go('/home',true);toast('데이터를 가져왔습니다.');});}catch(e){alertBox('가져오기 실패','이 목업에서 내보낸 정상 JSON 파일을 선택해 주세요.');}};f.click();});
 on('page',b=>{pages[b.dataset.key]=+b.dataset.page;render();});on('filter-reset',b=>{const f=b.closest('form');f.reset();$$('input',f).forEach(e=>{if(e.type!=='radio'&&e.type!=='checkbox')e.value='';});$$('select',f).forEach((e,n)=>e.selectedIndex=0);$$('[data-filter-check],[data-check-all]',f).forEach(c=>c.checked=true);const summary=$('[data-date-summary]',f);if(summary)summary.textContent='시작일 ~ 종료일';$$('.quick-dates .btn',f).forEach(c=>c.classList.remove('selected'));toast('검색 조건을 초기화했습니다. 조회를 눌러 결과에 적용하세요.');});
 on('quick-date',b=>{const f=b.closest('form'),days=+b.dataset.days;f.elements.to.value=days?date():'';f.elements.from.value=days?new Date(Date.now()-days*86400000).toLocaleDateString('sv-SE'):'';const label=$('[data-date-summary]',f);if(label)label.textContent=days?f.elements.from.value+' ~ '+f.elements.to.value:'시작일 ~ 종료일';$$('.quick-dates .btn',f).forEach(x=>x.classList.toggle('selected',x===b));});
