 on('date-done',b=>{const f=b.closest('form'),from=f.elements.from.value,to=f.elements.to.value;if(from&&to&&from>to)return alertBox('등록일','시작일은 종료일보다 늦을 수 없습니다.');$('[data-date-summary]',f).textContent=from||to?(from||'시작일')+' ~ '+(to||'종료일'):'시작일 ~ 종료일';b.closest('details').open=false;});
