 on('item-edit',b=>{const i=item(b.dataset.id);if(i.status==='D')return;if(i.draft)modal('임시 저장 확인',`<p>${esc(i.draft.draftAt)}에 임시 저장된 내용이 있습니다.</p><p>어느 버전을 수정하시겠습니까?</p>`,[{label:'취소',fn:(_,m)=>closeModal(m)},{label:'임시저장 수정하기',kind:'primary',fn:(_,m)=>{closeModal(m);edit={kind:'item',id:i.id,data:clone(i.draft),dirty:false};go('/items/'+i.id+'/edit/meta');}},{label:'검수완료 수정하기',fn:(_,m)=>{closeModal(m);edit={kind:'item',id:i.id,data:clone(i),dirty:false};go('/items/'+i.id+'/edit/meta');}}]);else go('/items/'+i.id+'/edit/meta');});
 on('status-save',b=>{
  const i=item(b.dataset.id);if(!i||i.status==='D'||statusEdit?.id!==i.id||!statusEdit.dirty)return;
  const s=clone(statusEdit.data),statusChanged=s.status!==i.status;
  if(!canStatusTransition(i.status,s.status)||statusChanged&&groupItems(i).some(v=>!canStatusTransition(v.status,s.status)))return alertBox('상태 정보 저장','변경할 수 없는 상태가 포함되어 있습니다. 폐기 문항은 복구할 수 없습니다.');
  if(s.status==='Y'&&(!i.unitCodes.length||!i.behavior||!i.difficulty||!i.answer))return alertBox('승인 검사','필수 메타정보 또는 OMR 정답이 없습니다. 문항 수정에서 입력해 주세요.');
  const impact=s.status==='D'?(i.passageId?'같은 세트 전체가 폐기되고 쌍둥이에서 제외됩니다.':'폐기 시 쌍둥이 문항에서 제외됩니다.'):(i.passageId&&statusChanged?'세트 문항 전체의 상태값이 함께 변경됩니다.':'');
  confirm('상태 정보 저장','저장하시겠습니까?'+(impact?'<br>'+impact:''),'저장',()=>{
   const targets=groupItems(i);if(statusChanged)targets.forEach(v=>v.status=s.status);i.usage=s.usage;i.online=s.online;
   if(s.status==='D'){const g=twinGroup(i);if(g)g.members=g.members.filter(v=>v!==(i.passageId||i.id));}
   save('문항 상태 저장 '+i.id);statusEdit=null;
   render();toast(storageOk?'상태 정보를 저장했습니다.':'현재 탭에 상태 정보를 반영했습니다. 브라우저 저장을 사용할 수 없습니다.');
  });
 });
 on('item-sources',b=>itemSources(+b.dataset.id));on('source-tab',b=>{closeModal();itemSources(+b.dataset.id,b.dataset.tab);});on('item-twins',b=>openTwins(+b.dataset.id));on('twins-tab',b=>{closeModal();openTwins(+b.dataset.id,b.dataset.tab);});on('twins-reset',b=>{closeModal();openTwins(+b.dataset.id,'add');});
 on('twins-add',b=>{const i=item(b.dataset.id),key=i.passageId||i.id,target=+b.dataset.member;let g=twinGroup(i),other=db.twins.find(x=>x.members.includes(target));if(!g){g={id:db.nextTwin++,type:i.passageId?'set':'single',members:[key],updated:date()};db.twins.push(g);}g.members=Array.from(new Set([...g.members,...(other?.members||[target])]));g.updated=date();if(other&&other.id!==g.id)db.twins=db.twins.filter(x=>x.id!==other.id);save('쌍둥이 그룹 병합 '+g.id);closeModal();openTwins(i.id,'add');toast('쌍둥이 관계를 추가했습니다. 기존 생성 이력은 유지합니다.');});
 on('twins-remove',b=>{const i=item(b.dataset.id),g=twinGroup(i),key=+b.dataset.member;if(g&&g.members.length>1){g.members=g.members.filter(v=>v!==key);save('쌍둥이 관계 해제 '+key);closeModal();openTwins(i.id);toast('현재 관계를 해제했습니다. 문항과 생성 이력은 유지합니다.');}});
 on('twin-generate',b=>{const i=item(b.dataset.id);if(i.working)return alertBox('쌍둥이 생성 진행','예시 생성이 진행 중입니다. 생성 방식·요청자 demo.editor·요청 시각 '+now());modal('쌍둥이 문항 생성',`<label><input type="radio" name="generate" value="COPY" checked>복제 (COPY)</label><p class="muted">현재 문항을 그대로 복제합니다.</p><label><input type="radio" name="generate" value="AI">AI 생성</label><p class="muted">목업에서는 예시 문항을 생성합니다. 실제 AI에 요청하지 않습니다.</p>${i.passageId?notice('세트에 속한 모든 문항이 함께 생성됩니다.'):''}`,[{label:'취소',fn:(_,m)=>closeModal(m)},{label:'생성 시작',kind:'primary',fn:(_,m)=>{const method=$('input[name=generate]:checked',m).value;closeModal(m);i.working=true;activeJobs++;save();render();toast('예시 생성 요청을 접수했습니다.');setTimeout(()=>{if(remotePending){activeJobs--;toast('다른 탭의 변경 때문에 예시 생성을 중단했습니다. 최신 데이터를 불러오세요.');return;}const original=groupItems(i),passage=i.passageId?db.nextPassage++:null,copies=original.map(v=>({...clone(v),id:db.nextItem++,version:Date.now(),passageId:passage,status:'R',method,draft:undefined,created:date(),generationHistory:[],working:false,deployed:[]}));db.items.push(...copies);let g=twinGroup(i);if(!g){g={id:db.nextTwin++,type:i.passageId?'set':'single',members:[i.passageId||i.id],updated:date()};db.twins.push(g);}g.members.push(passage||copies[0].id);const h={ids:copies.map(c=>c.id),method,at:now(),user:'demo.editor'};original.forEach(v=>{v.generationHistory.push(h);v.working=false;});activeJobs--;save('예시 쌍둥이 '+method+' 생성');if(current.startsWith('/items/'+i.id))render();toast('예시 문항 생성이 완료되었습니다.');},800);}}]);});
 on('twin-history',b=>{const i=item(b.dataset.id);modal('쌍둥이 생성 이력',table(['문항 ID','방식','요청자','생성일시'],i.generationHistory.flatMap(h=>h.ids.map(id=>tr([link(id,'/items/'+id),h.method,h.user,h.at]))),'아직 생성된 쌍둥이 문항이 없습니다.'),[{label:'닫기',fn:(_,m)=>closeModal(m)}],{wide:true});});
 for(const mode of ['add','update'])on('relation-'+mode,b=>{const i=item(b.dataset.id),row=b.closest('tr'),start=+row.querySelector('[name=start]').value,end=+row.querySelector('[name=end]').value;if(!start||!end||start<1||end<1)return errorIn(b.closest('.modal-overlay'),'페이지 시작과 끝을 1 이상으로 입력해 주세요.');const v={id:+b.dataset.source,start,end,usage:row.querySelector('[name=usage]').value};if(mode==='add')i.sourceRefs.push(v);else Object.assign(i.sourceRefs.find(x=>x.id===v.id),v);save('문항 출처 '+mode);toast('출처 연결 정보를 저장했습니다.');closeModal();itemSources(i.id);});
